import java.util.ArrayList;

interface SortingAlgorithm<T> {
    void sort(T[] arr);
}

class BubbleSort<T> implements SortingAlgorithm<T> {
    private final Comparator<T> comparator;
    private final boolean trackMetrics;
    private long comparisons;
    private long swaps;

    private BubbleSort(Builder<T> builder) {
        this.comparator = builder.comparator;
        this.trackMetrics = builder.trackMetrics;
    }

    @Override
    public void sort(T[] arr) {
        validateInput(arr);
        for (int i = 0; i < arr.length - 1; i++) {
            if (!performPass(arr, i)) break;
        }
    }

    public void sort(List<T> list) {
        if (list == null || list.size() < 2) return;
        for (int i = 0; i < list.size() - 1; i++) {
            if (!performPassOnList(list, i)) break;
        }
    }

    private boolean performPass(T[] arr, int passIndex) {
        boolean swapped = false;
        for (int j = 0; j < arr.length - passIndex - 1; j++) {
            recordComparison();
            if (comparator.compare(arr[j], arr[j + 1]) > 0) {
                swap(arr, j, j + 1);
                swapped = true;
            }
        }
        return swapped;
    }

    private boolean performPassOnList(List<T> list, int passIndex) {
        boolean swapped = false;
        for (int j = 0; j < list.size() - passIndex - 1; j++) {
            recordComparison();
            if (comparator.compare(list.get(j), list.get(j + 1)) > 0) {
                swapList(list, j, j + 1);
                swapped = true;
            }
        }
        return swapped;
    }

    private void swap(T[] arr, int i, int j) {
        T temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        recordSwap();
    }

    private void swapList(List<T> list, int i, int j) {
        T temp = list.get(i);
        list.set(i, list.get(j));
        list.set(j, temp);
        recordSwap();
    }

    private void recordComparison() {
        if (trackMetrics) comparisons++;
    }

